import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh, DoubleSide, SRGBColorSpace } = ctx.THREE;

  const root = new Group();
  root.userData.timelines = [];
  root.userData.handlers = {};

  const region = config.atlasRegion ?? config.atlas ?? {};
  const rect = [
    region.x ?? 0,
    region.y ?? 0,
    region.w ?? 512,
    region.h ?? 320,
  ];

  const aspect = rect[2] / rect[3];
  const baseHeight = 1.6;
  const geometry = new PlaneGeometry(baseHeight * aspect, baseHeight);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
    side: DoubleSide,
  });

  const mesh = new Mesh(geometry, material);
  mesh.visible = false;
  root.add(mesh);

  let disposed = false;
  let loadedTexture = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (disposed) {
        tex.dispose();
        return;
      }

      loadedTexture = tex;
      tex.colorSpace = SRGBColorSpace;
      tex.needsUpdate = true;

      const texW = tex.image?.width ?? rect[2];
      const texH = tex.image?.height ?? rect[3];
      const [rx, ry, rw, rh] = rect;

      const scaleX = rw / texW;
      const scaleY = rh / texH;
      const offsetX = rx / texW;
      const offsetY = ry / texH;

      const uvNode = uv().mul(vec2(scaleX, scaleY)).add(vec2(offsetX, offsetY));
      material.mapNode = texture(tex, uvNode);
      mesh.visible = true;
    });
  }

  root.userData.handlers.render = (_renderer, _scene, camera) => {
    root.quaternion.copy(camera.quaternion);
  };

  root.userData.cleanup = () => {
    disposed = true;
    root.userData.timelines.forEach((tl) => tl?.kill());
    if (loadedTexture) loadedTexture.dispose();
    geometry.dispose();
    material.dispose();
  };

  return root;
}
